'use strict';const fs=require('node:fs'),path=require('node:path');const root=path.resolve(__dirname,'..'),read=p=>fs.readFileSync(path.join(root,p),'utf8');const bundle=['src/engine.js','src/theme.js','src/widget.js'].map(read).join('\n');fs.mkdirSync(path.join(root,'dist'),{recursive:true});fs.writeFileSync(path.join(root,'dist/bangbom-chat.js'),bundle);const inline=s=>s.replace(/<\/script/gi,'<\\/script');const demo=read('demo/template.html').replace('/*__BUNDLE__*/',()=>inline(bundle)).replace('/*__DATA__*/',()=>inline(read('src/catalog.js')));fs.writeFileSync(path.join(root,'demo.html'),demo);console.log('Built dist/bangbom-chat.js and offline demo.html');
